set -euo pipefail
umask 077
output=human
previous=''
for option in "$@"; do
  if [[ "$previous" == --output ]]; then output="$option"; fi
  if [[ "$option" == --output=json ]]; then output=json; fi
  previous="$option"
done
for option in "$@"; do
  if [[ "$option" == --help || "$option" == -h ]]; then
